循环（for/while）.answer:
def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0: return False
    return True

函数定义与调用.answer:
def factorial(n):
    if n <= 1: return 1
    return n * factorial(n-1)

列表与元组.answer:
def dedup(lst):
    seen = set()
    result = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

字典与集合.answer:
def count_chars(s):
    d = {}
    for c in s:
        d[c] = d.get(c, 0) + 1
    return d

字符串操作.answer:
def word_freq(sentence):
    words = sentence.lower().split()
    d = {}
    for w in words:
        d[w] = d.get(w, 0) + 1
    return d

