异常处理.answer:
def safe_div(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

def retry(times):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for i in range(times):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if i == times - 1:
                        raise e
        return wrapper
    return decorator
